"""WIZBASE 자체 작성 문항 초안(AI 보조 작성, 인간 검수 전 = DRAFT). 비공개 시험문제·복원문제와 무관.
선택지는 문항별로 결정적으로 섞는다(정답 위치 편향 방지). 모든 문항은 objective(공식 가이드 bullet)에 연결된다."""
import random


def N(item_id, exam, domain, obj, family, stem, right, wrongs, why_right, cog="design", refs=None):
    multi = isinstance(right, (list, tuple))
    rights = list(right) if multi else [right]
    ch = [(t, why_right if i == 0 else "정답: 조건에 부합.", True) for i, t in enumerate(rights)] + [(t, w, False) for t, w in wrongs]
    it = {"item_id": item_id, "exam": exam, "domain": domain, "obj": obj, "family": family, "cog": cog, "stem": stem, "type": "multi" if multi else "single", "_ch": ch, "refs": refs or []}
    if multi:
        it["select_count"] = len(rights); it["scoring"] = "all_or_nothing"
    return it


def finalize(it):
    r = random.Random(it["item_id"])
    ch = list(it.pop("_ch"))
    r.shuffle(ch)
    it["choices"] = [{"id": "ABCDEFG"[i], "text": c[0], "why": c[1]} for i, c in enumerate(ch)]
    it["correct"] = ["ABCDEFG"[i] for i, c in enumerate(ch) if c[2]]
    return it


